/*
 * n2vt_abi.h -- the VideoToolbox video-encoder plug-in ABI of iOS 16.7.16 (20H392, iPhone X cache), as read out of the
 * dyld shared cache on 2026-11-11 (gpu/video/research/vtab.py, dis.py). LEAD-OWNED, FROZEN: workers do not edit this file;
 * post a request on the board.
 *
 * Evidence (addresses are unslid cache addresses):
 *   kVCH263VideoEncoderVTable @0x20ee20068 = { 0, &base @0x20ee20080, &class @0x20ee200d8 }
 *     base  = { version 1, derivedStorageSize 0xf0, equal 0, invalidate 0, finalize, copyDebugDescription, copyProperty,
 *               setProperty, 0, 0, 0 }                                   (11 pointer-sized slots, 0x58 bytes)
 *     class = { version 1, StartSession, EncodeFrame, CompleteFrames, CopySupportedPropertyDictionary, 0 ... }
 *   kParavirtualizedVideoEncoder vtable @0x1d69e8be8 (class version 4) names the later slots:
 *     +0x38 PrepareToEncodeFrames, +0x88 StartTileSession, +0x90 PrepareToEncodeTiles, +0x98 EncodeTile, +0xa0 CompleteTiles
 *   _ParavirtualizedVideoEncoder_StartSession @0x194ef33a4: x0 encoder, x1 session, x2 = CMVideoDimensions packed (w low 32)
 *   _ParavirtualizedVideoEncoder_EncodeFrame  @0x194ef3474: x0..x6 = encoder, frame, imageBuffer, &pts, &duration,
 *                                                           frameProperties, infoFlagsOut   (CMTime is passed by reference: 24 bytes)
 *   _VTEncoderSessionEmitEncodedFrame @0x194cd282c: x0 session, x1 frame, w2 status, w3 infoFlags, x4 sampleBuffer
 *   _VTRegisterVideoEncoder @0x194ccd294 = VTRegisterVideoEncoderWithInfo(codecType, NULL, createInstance)
 *   _VTRegisterVideoEncoderWithInfo @0x194ed7770: w0 codecType, x1 info dictionary (may be NULL), x2 createInstance
 * INFERRED (not read out of the code, taken from the decoder class's names and from the callers): the names of the class
 * slots +0x28 (SetProperties) and +0x30 (CopySerializableProperties); we leave both NULL as VCH263 does.
 *
 * SPDX-License-Identifier: MIT
 */
#ifndef N2VT_ABI_H
#define N2VT_ABI_H

#include "n2_apple.h"

typedef struct OpaqueVTVideoEncoder        *VTVideoEncoderRef;      /* a CMBaseObject of class VTVideoEncoderGetClassID() */
typedef struct OpaqueVTVideoEncoderSession *VTVideoEncoderSession;  /* VideoToolbox's side of one compression session */
typedef struct OpaqueVTVideoEncoderFrame   *VTVideoEncoderFrame;    /* VideoToolbox's token for one submitted frame */

/* CoreMedia's base class record: 11 pointer-sized slots (0x58 bytes) in this iOS. */
typedef struct n2_CMBaseClass {
	uint64_t        version;                /* 1 */
	size_t          derivedStorageSize;     /* bytes CMBaseObjectGetDerivedStorage() gives, zero-filled at creation */
	Boolean         (*equal)(CMBaseObjectRef a, CMBaseObjectRef b);                                 /* NULL */
	OSStatus        (*invalidate)(CMBaseObjectRef o);                                               /* may be NULL */
	void            (*finalize)(CMBaseObjectRef o);
	CFStringRef     (*copyDebugDescription)(CMBaseObjectRef o);
	OSStatus        (*copyProperty)(CMBaseObjectRef o, CFStringRef key, CFAllocatorRef a, void *valueOut);
	OSStatus        (*setProperty)(CMBaseObjectRef o, CFStringRef key, CFTypeRef value);
	void            *reserved8, *reserved9, *reserved10;                                            /* NULL */
} n2_CMBaseClass;

/* The encoder class record: version 1 uses the first four functions; the rest must be NULL (21 slots, 0xa8 bytes). */
typedef struct n2_VTVideoEncoderClass {
	uint64_t        version;                /* 1 */
	OSStatus        (*startSession)(VTVideoEncoderRef enc, VTVideoEncoderSession session, CMVideoDimensions dims);
	OSStatus        (*encodeFrame)(VTVideoEncoderRef enc, VTVideoEncoderFrame frame, CVImageBufferRef image,
	                               const CMTime *pts, const CMTime *duration, CFDictionaryRef frameProperties,
	                               uint32_t *infoFlagsOut);
	OSStatus        (*completeFrames)(VTVideoEncoderRef enc, const CMTime *completeUntilPTS);
	OSStatus        (*copySupportedPropertyDictionary)(VTVideoEncoderRef enc, CFDictionaryRef *dictOut);
	void            *setProperties;                 /* +0x28 NULL */
	void            *copySerializableProperties;    /* +0x30 NULL */
	void            *prepareToEncodeFrames;         /* +0x38 NULL */
	void            *reserved[9];                   /* +0x40 .. +0x80 NULL */
	void            *startTileSession;              /* +0x88 NULL */
	void            *prepareToEncodeTiles;          /* +0x90 NULL */
	void            *encodeTile;                    /* +0x98 NULL */
	void            *completeTiles;                 /* +0xa0 NULL */
} n2_VTVideoEncoderClass;

typedef struct n2_VTVideoEncoderVTable {
	const void                      *reserved;      /* NULL */
	const n2_CMBaseClass            *baseClass;
	const n2_VTVideoEncoderClass    *encoderClass;
} n2_VTVideoEncoderVTable;

_Static_assert(sizeof(n2_CMBaseClass) == 0x58, "CMBaseClass is 11 slots");
_Static_assert(sizeof(n2_VTVideoEncoderClass) == 0xa8, "VTVideoEncoderClass is 21 slots");
_Static_assert(__builtin_offsetof(n2_VTVideoEncoderClass, startTileSession) == 0x88, "tile slots");
_Static_assert(sizeof(n2_VTVideoEncoderVTable) == 0x18, "vtable is 3 slots");

typedef OSStatus (*n2_VTVideoEncoderCreateInstance)(uint32_t codecType, CFAllocatorRef allocator, VTVideoEncoderRef *instanceOut);

/* VideoToolbox exports (all verified present in the cache's export trie of VideoToolbox). */
extern CMTypeID  VTVideoEncoderGetClassID(void);
extern CMBaseObjectRef VTVideoEncoderGetCMBaseObject(VTVideoEncoderRef enc);
extern OSStatus  VTRegisterVideoEncoder(uint32_t codecType, n2_VTVideoEncoderCreateInstance create);
extern OSStatus  VTRegisterVideoEncoderWithInfo(uint32_t codecType, CFDictionaryRef info, n2_VTVideoEncoderCreateInstance create);
extern OSStatus  VTEncoderSessionSetPixelBufferAttributes(VTVideoEncoderSession session, CFDictionaryRef attributes);
extern OSStatus  VTEncoderSessionEmitEncodedFrame(VTVideoEncoderSession session, VTVideoEncoderFrame frame, OSStatus status,
                                                  uint32_t infoFlags, CMSampleBufferRef sampleBuffer);
/* Creating the object: CMDerivedObjectCreate(allocator, (const void *)&vtable, VTVideoEncoderGetClassID(), &object)
 * (call at 0x201e30384 in VCH263VideoEncoder_CreateInstance: x0 allocator, x1 vtable, x2 class id, x3 out). */
extern OSStatus  CMDerivedObjectCreate(CFAllocatorRef allocator, const void *vtable, CMTypeID classID, CMBaseObjectRef *objectOut);
extern void     *CMBaseObjectGetDerivedStorage(CMBaseObjectRef o);

/* Keys of the info dictionary given to VTRegisterVideoEncoderWithInfo (verified in _VTRegisterVideoEncoderWithInfo and in
 * _vtFilterRegistryItemByCodecTypeAndVideoEncoderSpecification @0x194ed8910). "CMClassImplementationID" is a plain string key. */
#define N2VT_INFO_IMPLEMENTATION_ID     N2STR("CMClassImplementationID")
#define N2VT_INFO_IMPLEMENTATION_NAME   N2STR("CMClassImplementationName")
extern const CFStringRef kVTVideoEncoder_IsHardwareAccelerated;    /* @0x1d69aad48: check the export with research/macho.py before linking */
extern const CFStringRef kVTVideoEncoder_Rating;                   /* @0x1d69aad50: same */

/* Our encoder IDs (what VTCopyVideoEncoderList shows and kVTVideoEncoderSpecification_EncoderID selects). */
#define N2VT_ID_AVC     "com.nord2.videotoolbox.videoencoder.avc1.n2avc"
#define N2VT_ID_HEVC    "com.nord2.videotoolbox.videoencoder.hvc1.vcp"     /* Apple's own software HEVC encoder, registered by us */
#define N2VT_ID_JPEG    "com.nord2.videotoolbox.videoencoder.jpeg.n2jpeg"

/* OSStatus values used by the plug-ins (public VTErrors.h / CMBase numbers). */
enum {
	N2_kVTPropertyNotSupportedErr   = -12900,
	N2_kVTParameterErr              = -12902,
	N2_kVTAllocationFailedErr       = -12904,
	N2_kVTVideoEncoderMalfunctionErr= -12912,
	N2_kVTInvalidSessionErr         = -12903,
	N2_kCMBaseObjectError_ValueNotAvailable = -12783,
};

/* Where the plug-in lives on the phone, and the entry VideoToolbox calls after dlopen (verified: _VTLoadVideoEncoders
 * @0x194ccd114 does dlopen(path, RTLD_LOCAL) + dlsym(name) + call for a fixed list; these two paths are in that list and exist
 * neither in the cache nor on the root file system). */
#define N2VT_ENCODER_PLUGIN_PATH        "/System/Library/VideoEncoders/Slim.videoencoder"       /* a Mach-O dylib FILE */
#define N2VT_ENCODER_PLUGIN_ENTRY       "SLIMEncoderRegister"                                   /* void (*)(void) */
#define N2VT_DECODER_PLUGIN_PATH        "/System/Library/VideoDecoders/Slim.videodecoder"       /* reserved: not installed in stage 1 */
#define N2VT_DECODER_PLUGIN_ENTRY       "SLIMRegister"

/* Switches: files in /private/var/db (their presence is the switch; read once at registration). */
#define N2VT_SWITCH_OFF         "/private/var/db/nord2-video-off"          /* register nothing */
#define N2VT_SWITCH_NO_AVC      "/private/var/db/nord2-video-no-avc"
#define N2VT_SWITCH_NO_HEVC     "/private/var/db/nord2-video-no-hevc"
#define N2VT_SWITCH_NO_JPEG     "/private/var/db/nord2-video-no-jpeg"
#define N2VT_SWITCH_CLAIM_HW    "/private/var/db/nord2-video-claim-hw"     /* register with IsHardwareAccelerated = true */
#define N2VT_SWITCH_QUIET       "/private/var/db/nord2-video-quiet"        /* no console lines */

#endif
